            /// <summary>列出匹配的可见顶层窗口（含空标题窗口；只需标题/进程时直接读 w.Title/w.Process）；候选窗口超过枚举上限且结果不足 limit 时抛 WINDOW_LIMIT_EXCEEDED。</summary>
            public static extern Win[] FindAll(string title = "", string process = "", string className = "", bool regex = false, bool hidden = false, int limit = 64);
            /// <summary>与 FindAll 相同的匹配与上限，但一次返回各窗口的信息快照（含 Bounds/State 与可继续操作的 Window 引用）；整次只计 1 次窗口观察，适合“列出后按位置/状态筛选”。</summary>
            public static extern WinInfo[] FindAllInfo(string title = "", string process = "", string className = "", bool regex = false, bool hidden = false, int limit = 64);
            /// <summary>列出后代子窗口（最多 64 个）；子窗口只可查询，不能激活/排列/关闭。</summary>
            public static extern Win[] ListChildren(Win window, string title = "", string className = "");
            /// <summary>重新验证窗口并读取最新信息（可返回）。</summary>
            public static extern WinInfo Info(Win window);
            /// <summary>激活顶层窗口（切换为前台；最小化的窗口会先还原）；无返回值，需要最新状态时调用 Info。</summary>
            public static extern void Activate(Win window);
            /// <summary>进程已运行则激活其主窗口，否则按 path 以普通权限启动并等待窗口；未运行且不启动时返回 null。目标窗口的身份和状态仍由宿主校验。</summary>
            public static extern Win? ActivateProcess(string process, string? path = null, string? title = null, string? className = null, bool regex = false, string? hotkey = null, bool launch = true);
            /// <summary>回到弹出面板前的前台窗口；没有记录时不操作。</summary>
            public static extern void RestoreForeground();
            /// <summary>设置顶层窗口位置和大小（物理像素）。</summary>
            public static extern void SetBounds(Win window, Rect bounds);
            /// <summary>设置顶层窗口状态（普通/最小化/最大化）。隐藏/显示用 SetVisible，置于其他窗口之下用 SendToBack。</summary>
            public static extern void SetState(Win window, string state);
            /// <summary>把顶层窗口吸附到屏幕的某个位置（取目标屏幕的工作区 WorkArea：已排除任务栏，物理像素；DPI 与窗口不可见的缩放边框由宿主处理，使可见部分紧贴工作区）。最大化/最小化的窗口先还原（等还原完成）再摆放；跨 DPI 屏幕移动后系统可能重算窗口大小，宿主在窗口稳定后复核并最多补一次。目标须为顶层窗口，拒绝 Quicker 自身窗口；计 1–4 次排列操作。移动与状态改变异步投递，目标窗口无响应（挂起）时 Snap 不会阻塞脚本。返回 bool：窗口稳定（连续两次读取相隔 50 毫秒相同，最多约 1 秒）后核实最终可见边界（maximize/restore 核实状态）在几个像素内才为 true，否则 false（不报错）。最多补一次且仅在稳定时。</summary>
            public static extern bool Snap(Win window, string position, string? screen = null);
            /// <summary>隐藏或显示顶层窗口（不激活）；异步投递，不等待目标窗口处理。隐藏后可用 FindAll(hidden: true) 找回。不能隐藏任务栏、桌面等外壳窗口（INVALID_ARGUMENT）。</summary>
            public static extern void SetVisible(Win window, bool visible);
            /// <summary>把顶层窗口置于其他窗口之下（先取消置顶）；异步投递，不等待目标窗口处理。</summary>
            public static extern void SendToBack(Win window);
            /// <summary>设置或取消置顶；返回调用后的实际置顶状态。需要切换时写 SetTopmost(w, !qk.Window.Info(w).Topmost)。</summary>
            public static extern bool SetTopmost(Win window, bool topmost = true);
            /// <summary>设置窗口不透明度。</summary>
            public static extern void SetOpacity(Win window, int alpha);
            /// <summary>发送关闭请求（程序可能询问保存）；不能关闭 Quicker 自身的窗口。</summary>
            public static extern void Close(Win window, bool kill = false);
            /// <summary>等待窗口达到状态；满足时返回窗口，超时返回 null。等待窗口关闭用 WaitForClose。</summary>
            public static extern Win? WaitFor(string title = "", string process = "", string className = "", string state = "exists", int timeoutMs = 10000);
            /// <summary>等待匹配的窗口全部关闭（含不可见窗口；本来就没有也算关闭）：关闭返回 true，超时返回 false（超时不抛错）。</summary>
            public static extern bool WaitForClose(string title = "", string process = "", string className = "", int timeoutMs = 10000);
            /// <summary>DWM 可见边界的锚点加 offset，读取失败时回退窗口外框，返回屏幕物理像素。前台 CaptureWindow 按外框采集，两者原点可能不同；不要用本方法转换截图/OCR 图内点，也不要猜边框补偿。屏幕 Vision.Find* 的结果已是屏幕坐标。</summary>
            public static extern Pt ToScreen(Win window, Pt offset, string anchor = "topLeft");
            /// <summary>向窗口（可为子控件）发送窗口消息并返回结果。拒绝 Quicker 自身窗口；计 1 次排列操作。</summary>
            public static extern long SendMessage(Win window, int message, long wParam = 0, object? lParam = null, bool post = false, int timeoutMs = 5000);
            /// <summary>向同一程序（可执行文件路径相同；资源管理器只限文件夹窗口）的顶层窗口发送关闭请求（程序可能询问保存或拒绝关闭），返回已发出的请求数（不等于实际关闭数）；部分失败时返回成功数；共享宿主进程或不适用的窗口报 WINDOW_ARRANGE_FAILED；计 1 次排列操作。</summary>
            public static extern int CloseSimilar(Win window, bool keepCurrent = false);
            /// <summary>最小化同一程序的顶层窗口（不抢焦点），返回受影响的窗口数（已最小化的不计）；其余规则同 CloseSimilar。</summary>
            public static extern int MinimizeSimilar(Win window);
            /// <summary>还原同一程序中已最小化的顶层窗口（不抢焦点），返回还原的窗口数；其余规则同 CloseSimilar。</summary>
            public static extern int RestoreSimilar(Win window);
            /// <summary>切换到同一程序的下一个（previous 为 true 时上一个）窗口并激活，返回该窗口；没有其他窗口返回 null。计 1 次激活操作。</summary>
            public static extern Win? ActivateSimilar(Win window, bool previous = false);
            /// <summary>贴边隐藏（由 Quicker 托管，脚本结束或停止后继续生效，需要撤销时显式 SetEdgeHide(window, false)）：enabled 为 true 启用、false 停用；返回调用后的实际状态（是否启用）。启用时窗口置顶；停用时停在贴边处的可见位置并取消置顶（不还原原位置）。计 1 次排列操作。</summary>
            public static extern bool SetEdgeHide(Win window, bool enabled = true, string edge = "auto");
        }

        /// <summary>向前台窗口模拟键盘输入（按键、组合键、输入文本、粘贴）；读写剪贴板见 qk.Clipboard。与 qk.Mouse 共用输入会话与限额；每次调用结束且没有按住的键时归还输入会话（之后的对话框操作不会中断脚本）；停止或结束时自动松开本次按下的键。每次运行最多输入 2000 个字符、256 次键盘调用；超出任一限额报 INPUT_LIMIT_EXCEEDED，且本次运行之后的键鼠输入全部失败。</summary>
        public static class Keyboard
        {
            /// <summary>按下并松开按键或组合键。</summary>
            public static extern void Press(string keys, int repeat = 1, int holdMs = 0);
            /// <summary>按下并保持一个键（最多同时 8 个）；脚本结束或停止时自动松开。</summary>
            public static extern void Down(string key);
            /// <summary>松开由 Down 按下的键；停止后的 finally 中也可调用（只释放：松开本次按住的全部键和按钮）。</summary>
            public static extern void Up(string key);
            /// <summary>读取按键状态（不注入输入）；Shift/Ctrl/Alt/Win 不分左右。</summary>
            public static extern bool IsDown(string key, bool toggled = false);
            /// <summary>逐字输入文本并返回输入的字符数；每次运行累计最多 2000 字符（\n 输入回车）。超出时本次调用一个字也不输入并报 INPUT_LIMIT_EXCEEDED（ActionErrorCode.InputLimitExceeded，不是 LIMIT_EXCEEDED），之后本次运行的键鼠输入（Press、Paste、Selection.GetText 等）全部失败：请先统计总长度，超出时截断或提示。</summary>
            public static extern int Type(string text, int intervalMs = 0);
            /// <summary>经剪贴板粘贴（Ctrl+V），写入内容不进剪贴板历史；计入 qk.Clipboard 写入限额（粘贴 1 次，恢复再 1 次）；单次最多 1 MiB。</summary>
            public static extern void Paste(string text, bool restore = true, int restoreDelayMs = 400);
            /// <summary>按 WinForms SendKeys 语法输入（+ Shift、^ Ctrl、% Alt、~ Enter、{KEY}、{KEY n}、分组 (...)）；修饰键只作用于字母、数字、空格、标点和 {KEY}（如 ^/ 为 Ctrl+/），{KEY} 另接受 Keyboard.Press 的键名（如 {MediaPlayPause}）。与 WinForms 不同：^A 为 Ctrl+A（不自动加 Shift），{A} 输入小写 a。</summary>
            public static extern void SendKeys(string keys);
            /// <summary>等待用户的物理按键（全局钩子，忽略模拟按键，不阻挡用户操作），返回键名（与 Keyboard.Press 相同，如 "Enter"、"A"；组合键条目带修饰键前缀，如 "Ctrl+Q"）；超时返回 null。有 Keyboard.Down/Mouse.Down 按住的键时不能调用。一次调用只返回一个键，命中后不再拦截其他按键；每次运行最多调用 1000 次（LIMIT_EXCEEDED）。</summary>
            public static extern string? WaitForKey(string? keys = null, int timeoutMs = 0, bool swallow = false);
            /// <summary>读取前台窗口输入法当前是否为中文（读不到状态视为 false）。只读取、不记录恢复基线，停止后的 finally 中也可调用。恢复写法：var was = qk.Keyboard.GetIme(); qk.Keyboard.SetIme(false); try { … } finally { qk.Keyboard.SetIme(was); }</summary>
            public static extern bool GetIme();
            /// <summary>设置前台窗口输入法的中/英文状态（无返回值）。已知当前已是目标状态时不发送任何按键或消息（切换热键多为按一次翻转，重复发送会切反）；否则设置中配置了输入法切换热键时经键盘输入发送该热键（异步生效），否则发送输入法消息；之后最多等待 300ms 确认（部分输入法不报告状态，不保证）。停止后的 finally 中：已是目标状态或本次运行从未调用 SetIme 时不做任何事（后者记日志）；否则只允许恢复到本次运行首次调用 SetIme 前的状态（只发输入法消息，不发按键），其他值报 CAPABILITY_DENIED。</summary>
            public static extern void SetIme(bool chinese);
        }

        /// <summary>模拟鼠标移动、点击、拖动与滚轮（坐标为屏幕物理像素）；不靠坐标操作控件见 qk.Uia.Act。每次运行最多 100 次点击、120 格滚轮；没有按住的按钮时每次调用结束即归还输入会话。</summary>
        public static class Mouse
        {
            /// <summary>当前鼠标位置（只读，不占用输入会话）。</summary>
            public static extern Pt GetPosition();
            /// <summary>移动到屏幕点；返回移动后的位置。</summary>
            public static extern Pt MoveTo(Pt to, int durationMs = 0);
            /// <summary>相对当前位置移动。</summary>
            public static extern Pt MoveBy(int dx, int dy);
            /// <summary>点击；返回点击位置。</summary>
            public static extern Pt Click(Pt? at = null, string button = "left", int count = 1);
            /// <summary>在当前位置按下并保持按钮（计入点击次数）；脚本结束或停止时自动松开。</summary>
            public static extern void Down(string button = "left");
            /// <summary>松开由 Down 按下的按钮（只释放）；停止后的 finally 中也可调用。</summary>
            public static extern void Up(string button = "left");
            /// <summary>滚动滚轮；每次运行累计最多 120 格。</summary>
            public static extern Pt Scroll(int clicks, bool horizontal = false);
            /// <summary>按住左键从当前位置拖到目标屏幕点后松开；返回拖动后的位置。</summary>
            public static extern Pt DragTo(Pt to, int durationMs = 300);
            /// <summary>回到 qk.Context.Mouse：弹出面板前的鼠标位置；没有面板（热键、调试运行）时回到运行开始时的鼠标位置；已在该处时不移动。只移动不点击，停止后的 finally 中也可调用。点击后复位推荐写 try { … } finally { qk.Mouse.RestorePosition(); }（正常结束、出错、停止都会复位）。</summary>
            public static extern Pt RestorePosition();
            /// <summary>当前鼠标指针形状：arrow|iBeam|hand|wait|appStarting|cross|no|help|sizeAll|sizeNs|sizeWe|sizeNwse|sizeNesw|upArrow，隐藏为 "hidden"，其他为 "unknown"。只读。</summary>
            public static extern string GetCursor();
        }

        /// <summary>系统剪贴板的读写（文本、HTML、图片、文件列表）；读取前台选中内容见 qk.Selection。宿主负责 STA、重试与历史隐藏。每次运行最多 64 次操作、32 次写入，文本单次最多 1 MiB；停止后的 finally 中仍可调用（WaitForChange 除外）。</summary>
        public static class Clipboard
        {
            /// <summary>读取剪贴板文本；无文本返回 null。</summary>
            public static extern string? GetText();
            /// <summary>读取 HTML 片段正文（去掉 CF_HTML 头）；没有返回 null。</summary>
            public static extern string? GetHtml();
            /// <summary>按格式读取并以文本返回；没有该格式返回 null。</summary>
            public static extern string? Get(string format);
            /// <summary>剪贴板中的文件/文件夹路径；没有返回空数组。</summary>
            public static extern string[] GetFiles();
            /// <summary>读取剪贴板图片；没有图片返回 null；剪贴板被占用或图片数据无法读取报 CLIPBOARD_UNAVAILABLE。</summary>
            public static extern Img? GetImage();
            /// <summary>把图片写入剪贴板（PNG 与位图格式）。</summary>
            public static extern void SetImage(Img image);
            /// <summary>写入文本；空文本等于清空。</summary>
            public static extern void SetText(string text, bool noHistory = false);
            /// <summary>写入 HTML（片段或完整文档）。</summary>
            public static extern void SetHtml(string html, string? text = null);
            /// <summary>写入文件列表（路径须存在）；校验路径会探测本机文件。</summary>
            public static extern void SetFiles(IEnumerable<string> paths, bool cut = false);
            /// <summary>按格式写入。</summary>
            public static extern void Set(string format, object data);
            /// <summary>清空剪贴板。</summary>
            public static extern void Clear(bool history = false);
            /// <summary>等待剪贴板内容变化；超时返回 false。</summary>
            public static extern bool WaitForChange(int timeoutMs = 5000);
        }

        /// <summary>本机文件与文件夹（读写、复制、压缩、搜索）以及资源管理器当前文件夹；用关联程序打开文件见 qk.Process.Open。文本默认严格 UTF-8（BOM 优先）；ReadBytes/ReadText/WriteBytes/WriteText/AppendText 单次最多 16 MiB（Copy/Move/Zip/Unzip/Hash 不受此限）；覆盖/递归默认关闭；删除不进回收站；临时文件建议放在 GetRunTempDirectory()。WriteText/AppendText 从不写 BOM（"utf-8-bom" 不是编码名）；给 Excel 打开的 UTF-8 CSV 请写 "\uFEFF" + 文本（或先用 WriteBytes 写 EF BB BF）；AppendText 在文件不存在时创建。常见错误码：FILE_NOT_FOUND、ACCESS_DENIED、FILE_FAILED（目标已存在、被占用等）、LIMIT_EXCEEDED。</summary>
        public static class Files
        {
            /// <summary>将路径规范化为绝对路径（相对路径基于 Quicker 当前目录）。</summary>
            public static extern string GetFullPath(string path);
            /// <summary>当前动作的本机持久数据目录（完整路径，不自动创建）；子程序使用调用方目录。首次写入前 CreateDirectory。不随动作同步或备份；删除动作时可选移入 Windows 回收站。</summary>
            public static extern string GetActionDataDirectory();
            /// <summary>本次根运行专属的临时文件夹（完整路径，不以 \ 结尾），首次调用时创建；qk.Actions.Call 调用的子脚本得到同一个文件夹。运行结束（正常、异常、停止、超时）后由 Quicker 递归删除，脚本不必在 finally 里删除（停止后 finally 也不能调用 Files.Delete）。</summary>
            public static extern string GetRunTempDirectory();
            /// <summary>文件或文件夹存在时都返回 true（区分用 Info(path)?.IsDirectory）。</summary>
            public static extern bool Exists(string path);
            /// <summary>文件或目录的基本信息；不存在返回 null。</summary>
            public static extern PathInfo? Info(string path);
            /// <summary>读取文件字节；单次最多 16 MiB。</summary>
            public static extern byte[] ReadBytes(string path);
            /// <summary>读取文本文件；单次最多 16 MiB。</summary>
            public static extern string ReadText(string path, string encoding = "utf-8");
            /// <summary>写入文件字节；单次最多 16 MiB。</summary>
            public static extern void WriteBytes(string path, byte[] bytes, bool overwrite = false);
            /// <summary>写入文本文件；单次最多 16 MiB。</summary>
            public static extern void WriteText(string path, string text, bool overwrite = false, string encoding = "utf-8");
            /// <summary>追加文本（文件不存在时创建，不写 BOM）；单次最多 16 MiB。</summary>
            public static extern void AppendText(string path, string text, string encoding = "utf-8");
            /// <summary>列出目录中的文件（完整路径）；最多 10000 项，不遍历链接。</summary>
            public static extern string[] ListFiles(string directory, string pattern = "*", bool recursive = false);
            /// <summary>列出目录中的子目录（完整路径）；最多 10000 项，不遍历链接。</summary>
            public static extern string[] ListDirectories(string directory, string pattern = "*", bool recursive = false);
            /// <summary>创建目录（含上级）并返回绝对路径；已存在时直接返回（幂等）。</summary>
            public static extern string CreateDirectory(string path);
            /// <summary>复制文件；不受 16 MiB 限制（该限制只针对 Read*/Write*）。目标所在文件夹必须已存在（先 qk.Files.CreateDirectory(Path.GetDirectoryName(dest))）；目标已存在且 overwrite 为 false 时报 FILE_FAILED。</summary>
            public static extern void Copy(string source, string destination, bool overwrite = false);
            /// <summary>移动或重命名文件/目录（目录不支持覆盖）；仅大小写不同的改名取决于文件系统（NTFS 可用，部分虚拟盘静默不生效）。不受 16 MiB 限制；目标所在文件夹必须已存在。</summary>
            public static extern void Move(string source, string destination, bool overwrite = false);
            /// <summary>删除文件或目录（默认不经过回收站；recycle: true 移到回收站）；路径不存在时什么也不做；停止后的 finally 中不可调用。</summary>
            public static extern void Delete(string path, bool recursive = false, bool recycle = false);
            /// <summary>把文件或文件夹（只含其内容，不含外层文件夹名；保留空子文件夹；UTF-8 文件名）压缩为 zip；zipPath 所在文件夹须已存在且不能在源文件夹内；source 末尾的 \ 忽略；单个文件在 zip 中只用文件名（磁盘根下的文件也是）；先写临时文件，失败或停止不留下半个 zip。</summary>
            public static extern void Zip(string source, string zipPath, bool overwrite = false);
            /// <summary>解压 zip 到目录（不存在则创建；不能是磁盘根目录）。先整体检查再写出：条目路径越出目录（../、绝对路径、盘符）、含 . 或 .. 层级、以点或空格结尾、Windows 设备名（CON、NUL、COM1 等）或冒号、zip 内文件与文件夹同名、不支持的压缩方式、加密或损坏的 zip 报 ZIP_FAILED 且不写任何文件；超过 10000 个条目或解压后超过 1 GiB 报 LIMIT_EXCEEDED。写出中途失败（停止、实际解压超过 1 GiB、磁盘错误）时删除本次新建的全部文件与文件夹。文件名按 UTF-8，旧中文 zip 按 GBK（系统代码页）。还原文件修改时间（文件夹时间不还原）。</summary>
            public static extern void Unzip(string zipPath, string directory, bool overwrite = false);
            /// <summary>已知文件夹的完整路径（不以 \ 结尾）；本机没有该文件夹报 FILE_NOT_FOUND。</summary>
            public static extern string GetKnownFolder(string name);
            /// <summary>在资源管理器中打开所在文件夹并选中（1–100 个路径；须存在，否则 FILE_NOT_FOUND；多个时须在同一文件夹，否则 INVALID_ARGUMENT；不等待窗口出现）。用户配置了其他文件管理器时只定位第一个。路径末尾的 \ 忽略。每次运行最多 20 次（LIMIT_EXCEEDED）。</summary>
            public static extern void Reveal(params string[] paths);
            /// <summary>当前资源管理器窗口的文件夹（桌面返回桌面路径）；不在资源管理器中返回 null。</summary>
            public static extern string? GetExplorerPath();
            /// <summary>让资源管理器窗口的活动标签页转到指定文件夹（文件夹须存在，否则 FILE_NOT_FOUND）。window 为 null 时作用于前台窗口；也可传入 Win（如 qk.Window.Find(className: "CabinetWClass")、qk.Context.ActiveWindow）。目标不是资源管理器（桌面、其他程序）时报 EXPLORER_NOT_FOUND，此时可用 qk.Process.Open(directory) 新开窗口。在打开/另存为对话框中切换路径见 qk.Uia.SetDialogPath。</summary>
            public static extern void SetExplorerPath(string directory, Win? window = null);
            /// <summary>用 Everything 搜索文件和文件夹并返回完整路径（Everything 须正在运行，否则 EVERYTHING_UNAVAILABLE；其他失败 EVERYTHING_FAILED）。排除 Office 临时文件（~$ 开头）最稳的做法是在 C# 中二次过滤：.Where(p =&gt; !Path.GetFileName(p).StartsWith("~$"))。</summary>
            public static extern string[] Search(string query, int limit = 100, bool regex = false, string? sort = null, bool descending = false);
            /// <summary>文件内容的哈希（流式计算，不受 16 MiB 限制，最大 16 GiB，超出 LIMIT_EXCEEDED；可被停止打断）；结果与 qk.Text.Hash(qk.Files.ReadBytes(path)) 相同。文件不存在或是文件夹报 FILE_NOT_FOUND。</summary>
            public static extern string Hash(string path, string algorithm = "sha256", string output = "hex");
            /// <summary>用户最近使用的文件（Windows 的 Recent 文件夹），按最近使用时间倒序：快捷方式先按更新时间排序，再惰性解析 .lnk，凑够 limit 条匹配结果就停止；目标已不存在的、重复的、文件夹（includeFolders 为 true 时保留）、扩展名不符的都会跳过。网络目标（UNC 路径、映射的网络盘）不探测是否存在（断开的网络位置会卡很久），按原样返回，IsDirectory 为 false，可能已不存在。只读 Recent 文件夹并探测本地目标是否存在，不读文件内容。没有记录返回空数组。</summary>
            public static extern RecentFile[] ListRecent(int limit = 20, string? extension = null, bool includeFolders = false);
        }

        /// <summary>直接发送 HTTP 请求与下载文件（不经浏览器）；操作网页见 qk.Browser。仅 http/https，使用 Quicker 代理设置，不共享 Cookie；Send/GetText/PostJson 不自动跳转，正文各限 4 MiB。timeoutMs 为单次超时（Send/GetText/PostJson 默认 60000，Download 默认 0；0 为只受动作超时约束，动作超时始终有效），超时取消请求并报 HTTP_TIMEOUT（服务端可能已处理）。常见错误码：HTTP_FAILED（网络失败、重定向过多）、HTTP_STATUS_FAILED（非 2xx）、LIMIT_EXCEEDED。</summary>
        public static class Http
        {
            /// <summary>发送请求并返回响应；非 2xx 仍返回结果（看 StatusCode/IsSuccess）；不自动跳转，文本正文与响应各限 4 MiB；给出 form/files 时按 multipart/form-data 上传（method 须为 POST/PUT，body 须为 null）。</summary>
            public static extern HttpResult Send(string url, string method = "GET", string? body = null, string contentType = "application/json", IDictionary<string, string>? headers = null, IDictionary<string, string>? form = null, IDictionary<string, string>? files = null, int timeoutMs = 60000);
            /// <summary>GET 并返回响应文本；非 2xx 抛 HTTP_STATUS_FAILED。</summary>
            public static extern string GetText(string url, int timeoutMs = 60000);
            /// <summary>POST JSON 并返回响应文本；非 2xx 抛 HTTP_STATUS_FAILED。</summary>
            public static extern string PostJson(string url, string json, int timeoutMs = 60000);
            /// <summary>下载到文件并返回保存的完整路径；最多 512 MiB，跟随最多 5 次重定向；非 2xx 抛错，失败不留残缺文件。</summary>
            public static extern string Download(string url, string path, bool overwrite = false, IDictionary<string, string>? headers = null, int timeoutMs = 0);
        }

        /// <summary>启动程序、用关联程序打开文件/网址、运行命令行并读取输出、列出进程、按 CPU/内存排名（ListUsage）与结束进程；在已打开的程序内部执行代码见 qk.Apps。以普通（非提升）权限启动。Run 被停止或 timeoutMs 到期时停止等待并尽力结束进程树。常见错误码：PROCESS_FAILED（启动失败）、PROCESS_TIMEOUT（Run 超时）、LIMIT_EXCEEDED（输出或列表超限）。</summary>
        public static class Process
        {
            /// <summary>以普通权限启动程序并返回 PID；不等待，停止脚本不会结束它。</summary>
            public static extern int Start(string executable, string[]? arguments = null, string workingDirectory = "");
            /// <summary>用关联程序打开文件、文件夹或网址。</summary>
            public static extern void Open(string target);
            /// <summary>以普通权限运行命令行程序并等待退出（隐藏窗口）；返回退出码与输出，输出每路最多 512K 字符。</summary>
            public static extern ProcResult Run(string executable, string[]? arguments = null, string workingDirectory = "", string encoding = "utf-8", int timeoutMs = 0);
            /// <summary>列出当前登录会话的进程（最多 4096 项）。</summary>
            public static extern ProcInfo[] List(string? name = null);
            /// <summary>当前登录会话中占用最高的进程（只读）：sort 为 cpu（默认）或 memory，limit 1–100（默认 10）；name 只统计该进程名（规则同 Process.List：不含路径，可省略 .exe，不区分大小写）。CPU 取约 0.5 秒内两次采样的差值（调用会阻塞约半秒，可被停止打断），按处理器数归一；MemoryBytes 为工作集。读不到的进程（采样期间退出）直接跳过，不报错；采样期间新启动的进程不计入；同名多进程各算一项。</summary>
            public static extern ProcUsage[] ListUsage(int limit = 10, string sort = "cpu", string? name = null);
            /// <summary>结束进程（不含子进程），返回结束的进程数（没有在运行为 0，不报错）。Kill(pid) 结束指定进程（只能是当前登录会话中的进程）；Kill(name) 结束当前会话中全部同名进程（名称规则同 List）。拒绝其他会话的进程、Quicker 自身及辅助进程、资源管理器与关键系统进程（INVALID_ARGUMENT，一个都不结束）；无权限（如管理员进程）报 PROCESS_FAILED（按名称时全部失败才报）。可能丢失未保存数据。</summary>
            public static extern int Kill(int pid);
            /// <summary>结束进程（不含子进程），返回结束的进程数（没有在运行为 0，不报错）。Kill(pid) 结束指定进程（只能是当前登录会话中的进程）；Kill(name) 结束当前会话中全部同名进程（名称规则同 List）。拒绝其他会话的进程、Quicker 自身及辅助进程、资源管理器与关键系统进程（INVALID_ARGUMENT，一个都不结束）；无权限（如管理员进程）报 PROCESS_FAILED（按名称时全部失败才报）。可能丢失未保存数据。</summary>
            public static extern int Kill(string name);
        }

        /// <summary>Img 图片的读取、生成二维码、处理与保存为文件（路径规则与 qk.Files 相同）；截屏见 qk.Screen，找图/OCR/识别二维码见 qk.Vision。Img 仅本次运行有效（不能返回或写入 State）；每次运行最多同时存活 32 个、累计创建 1024 个，单图最多 4000 万像素、单边 32768，存活像素 512 MiB。</summary>
        public static class Image
        {
            /// <summary>读取图片（png/jpg/gif/bmp/tif/ico，不支持 webp；取第一帧，按 EXIF 方向转正）。路径规则与 qk.Files 相同（可用 UNC），网址最多 32 MiB、30 秒；数据（含 Base64/data URI）最多 64 MiB；ftp:/file: 等其他协议报 INVALID_ARGUMENT，无法解码报 IMAGE_DECODE_FAILED。</summary>
            public static extern Img Load(object source);
            /// <summary>保存为文件并返回完整路径；格式按扩展名（png|jpg|jpeg|bmp|gif|tif|tiff）。路径规则与 qk.Files 相同；写同目录临时文件后替换，已存在且未 overwrite 报 FILE_FAILED，编码失败报 IMAGE_ENCODE_FAILED。</summary>
            public static extern string Save(Img image, string path, int quality = 90, bool overwrite = false);
            /// <summary>生成二维码图片（纠错级别 Q）；文本超出容量报 INVALID_ARGUMENT。识别二维码见 qk.Vision.ReadQr。</summary>
            public static extern Img CreateQr(string text, int size = 256, Img? icon = null, string darkColor = "#000000", string lightColor = "#FFFFFF", bool quietZone = true);
        }

        /// <summary>获取屏幕图像：截屏、截窗口、框选截图、Quicker 截图、取色与显示器信息（屏幕物理像素）；只要坐标不要图像见 qk.Ui.PickArea。PickCapture 与 CapturePro 合计每次运行 64 次；截屏计入每次运行 1000 次截图；停止脚本会关闭框选界面。</summary>
        public static class Screen
        {
            /// <summary>截取屏幕。</summary>
            public static extern Img Capture(Rect? area = null, string screen = "all");
            /// <summary>前台截图按窗口快照 Bounds（外框）采集，与 ToScreen 优先使用的 DWM 可见边界原点可能不同。图内识别点不能直接传 ToScreen；需要实时定位点击时优先使用窗口范围的 Vision.Find*，其结果已是屏幕坐标。</summary>
            public static extern Img CaptureWindow(Win window, bool background = false);
            /// <summary>由用户框选区域并截图；取消返回 null。脚本被停止时框选界面随之关闭。</summary>
            public static extern CaptureResult? PickCapture(bool detect = true, int delayMs = 0);
            /// <summary>打开 Quicker 截图；取消返回 null；截图不写入截图历史。capture/captureNow 在用户确认后以 CaptureResult.Image 返回截图。</summary>
            public static extern CaptureResult? CapturePro(string mode = "capture");
            /// <summary>读取屏幕点（Pt，物理像素）的颜色，返回 "#RRGGBB"；不计入 1000 次截图（适合轮询）；点不在屏幕上报 INVALID_ARGUMENT。</summary>
            public static extern string GetPixel(Pt point);
            /// <summary>全部显示器信息（主屏在前）；ScreenInfo.Id 可传给 qk.Sys.GetBrightness/SetBrightness 的 screen。</summary>
            public static extern ScreenInfo[] List();
        }

        /// <summary>在屏幕或图片中识别内容（找图、找色、找字、OCR、识别二维码）；截图本身见 qk.Screen，生成二维码见 qk.Image.CreateQr。结果为屏幕坐标（传入 Img 时为图内坐标）；area 与 window 都为 null 时搜索全部显示器，给出 window 时只在窗口内搜索（找字/OCR 在 area 与 window 都为 null 时逐块显示器识别再合并）；没找到返回空数组。每次运行最多 1000 次截图（与 qk.Screen.Capture/CaptureWindow 共用）：FindImage/FindColor/FindText/Ocr(Rect 或 null) 每次调用计 1 次，timeoutMs 重试的每一轮（每 300 毫秒）再计 1 次，FindText（area 与 window 都为 null）与 Ocr(null) 每块显示器各计 1 次；Ocr(Img)、ReadQr 与 qk.Screen.GetPixel 不计。长时间监视请先调大动作超时（默认 30 秒墙钟；如设为 40 分钟或 0=不限制），再控制总次数在约 950 次内（如 30 分钟每 2 秒查一次；每秒一次约 16 分钟就会 LIMIT_EXCEEDED），或先用 GetPixel 轮询已知点，变化后再搜索。另限 100 次二维码。OCR 只用本机 OCR Agent（不联网、不自动下载模型；不限 OCR 次数、像素与行数），错误码：OCR_UNAVAILABLE（未安装，消息附安装方法）、OCR_TIMEOUT、OCR_FAILED。</summary>
        public static class Vision
        {
            /// <summary>在屏幕中找模板图，按相似度降序返回命中；没找到返回空数组。按 RGB 比较，忽略模板与屏幕的透明度（透明像素按其 RGB 参与比较）。</summary>
            public static extern Hit[] FindImage(Img template, Rect? area = null, Win? window = null, double similarity = 0.9, int limit = 1, int timeoutMs = 0);
            /// <summary>找颜色，返回命中点；没找到返回空数组。每次调用计 1 次截图。</summary>
            public static extern Pt[] FindColor(string color, Rect? area = null, Win? window = null, int tolerance = 0, int limit = 1);
            /// <summary>用本机 OCR 在屏幕上找文字（行内包含、忽略大小写，每行取第一处）；没找到返回空数组。命中的 Bounds/Center 按子串在行内的字符位置比例估算（不等宽字体有偏差），Score 为该行的 OCR 置信度。area/window 都为 null 时逐块显示器识别；每轮识别单次超时 30 秒（OCR_TIMEOUT）。</summary>
            public static extern Hit[] FindText(string text, Rect? area = null, Win? window = null, int timeoutMs = 0, string model = "small", bool detectOrientation = false);
            /// <summary>用本机 OCR Agent 识别文字（不联网、不自动下载模型），返回全部行（返回值经编码最多 10000 项 / 1 MiB，大结果请自行截取）。超时报 OCR_TIMEOUT，未安装报 OCR_UNAVAILABLE（消息附安装方法），其他失败报 OCR_FAILED。识别表格用 OcrTable。</summary>
            public static extern OcrResult Ocr(object? source = null, string model = "small", bool detectOrientation = false, int timeoutMs = 30000);
            /// <summary>2.3.36 起使用本地 small 识字＋在线表格处理，会上传原图和本地识字结果，需要登录有效会员、联网及事先在识别结果窗同意上传；首版仅支持 x64。脚本不会自动下载组件或弹出上传确认。返回 TSV、HTML、行列数、单元格（含合并跨度与位置）和表头行数；文字模型固定，无 model 参数。未同意报 OCR_UPLOAD_CONSENT_REQUIRED，缺本地组件报 OCR_UNAVAILABLE；登录、会员、限流、超时及服务不可用会返回对应 OCR 错误码。</summary>
            public static extern OcrTableResult OcrTable(object? source = null, bool detectOrientation = false, int timeoutMs = 30000);
            /// <summary>识别图中的二维码；没有返回空数组。单图最多 1600 万像素，每次运行最多 100 次。生成二维码见 qk.Image.CreateQr。</summary>
            public static extern string[] ReadQr(Img image);
        }

        /// <summary>浏览器中的网页（标签页、元素、表单、页面脚本），经 Quicker 浏览器扩展读取和操作；单纯请求网址或下载见 qk.Http。Chrome/Edge 等需安装并连接扩展（Open 与 SearchBookmarks 不经扩展）。目标浏览器为前台/最近使用的已连接浏览器，本次运行内不变；tabId 为 null 表示其当前标签页。错误码：BROWSER_UNAVAILABLE（没有已连接的扩展）、BROWSER_FAILED（扩展返回错误、找不到元素、标签页已关闭）、BROWSER_TIMEOUT（扩展无响应）。</summary>
        public static class Browser
        {
            /// <summary>用浏览器打开网址（启动程序，不经扩展）；启动失败报 PROCESS_FAILED。</summary>
            public static extern void Open(string url, string browser = "default");
            /// <summary>前台浏览器当前标签页的网址；前台不是浏览器或其扩展未连接时返回 null（不是错误；其他 Browser 调用仍可能作用于另一个已连接的浏览器，没有时报 BROWSER_UNAVAILABLE）；已连接但读取标签页失败报 BROWSER_FAILED。</summary>
            public static extern string? GetUrl();
            /// <summary>目标浏览器（首次调用时选定的已连接浏览器，本次运行内不变）的全部标签页。</summary>
            public static extern Tab[] ListTabs();
            /// <summary>在目标浏览器新标签页打开网址并返回标签页 Id；网址规则同 Open。</summary>
            public static extern int OpenTab(string url, bool wait = true);
            /// <summary>激活标签页。</summary>
            public static extern void ActivateTab(int tabId);
            /// <summary>关闭标签页。</summary>
            public static extern void CloseTab(int tabId);
            /// <summary>在页面中执行 JS 并返回结果（JSON 数据：Dictionary/List/string/bool 或 null；整数为 long、小数为 decimal，用 Convert.ToInt32(x)/Convert.ToDouble(x) 转换，不要 (int)x 强转）。MV3 扩展需开启“允许运行用户脚本”。</summary>
            public static extern object? Eval(string script, int? tabId = null, int frameId = 0, int timeoutMs = 30000);
            /// <summary>操作页面元素；在 timeoutMs 内找不到元素报 BROWSER_FAILED，扩展无响应报 BROWSER_TIMEOUT。</summary>
            public static extern void Act(string target, string action = "click", string? value = null, int? tabId = null, int timeoutMs = 10000);
            /// <summary>等待元素出现和/或网址匹配（两者都给时须同时满足，共用 timeoutMs；页面跳转后继续等待）；满足返回 true，超时返回 false。</summary>
            public static extern bool WaitFor(string? target = null, string? urlPattern = null, int timeoutMs = 10000, int? tabId = null);
            /// <summary>按列表模板提取当前页数据：每行一个字典（列 key → string，缺失为 null）。没有匹配行时 allowEmpty 为 false 报 BROWSER_FAILED（e.Detail 为 LIST_ROWS_NOT_FOUND）；网址与模板不符 BROWSER_FAILED（e.Detail 为 URL_PATTERN_MISMATCH）；模板无效 INVALID_ARGUMENT；需要新版（MV3）扩展。</summary>
            public static extern List<Dictionary<string, object?>> Extract(string template, int? tabId = null, int limit = 500, bool allowEmpty = false, int timeoutMs = 30000);
            /// <summary>按表单模板填写页面：扩展先预检全部字段，必填失败时不写入任何字段。</summary>
            public static extern FillResult Fill(string template, IDictionary<string, object?> data, int? tabId = null, bool dryRun = false, string failOn = "required", int timeoutMs = 30000);
            /// <summary>把本机文件放入页面的文件输入框（浏览器按路径读取文件并显示调试提示条）。</summary>
            public static extern void Upload(string target, IEnumerable<string> files, int? tabId = null, string? urlPattern = null, int timeoutMs = 30000);
            /// <summary>执行浏览器扩展后台命令并返回结果。拒绝（INVALID_ARGUMENT）：读写或运行本机文件的命令（上传/拖放/下载/打开下载文件/写入下载文件夹的截图与归档）、调试协议、删除浏览数据、读取或删除历史、扩展自身存储、未给 url 的 Cookie 命令、已有专门方法的 page.* 命令、租约与诊断命令。</summary>
            public static extern object? Command(string command, object? arguments = null, int? tabId = null, int timeoutMs = 30000);
            /// <summary>在本机浏览器书签中搜索：直接读浏览器的 Bookmarks 文件，不需要浏览器扩展，浏览器也不用开着。query 的每个词都须出现在标题、网址或文件夹中（不区分大小写），标题命中的排前面。只覆盖各浏览器的默认用户配置（其他配置文件的书签搜不到）；不读取浏览历史、Cookie 或已保存的密码。</summary>
            public static extern Bookmark[] SearchBookmarks(string query, int limit = 20, string? browser = null);
        }

        /// <summary>在 Office/WPS/Adobe/CAD 等程序内部执行代码或调用插件命令；启动程序见 qk.Process。支持 Office/WPS VBA、Adobe JS、AutoCAD 命令、Rhino 脚本与软件连接插件命令，经低权限代理执行（不在 Quicker 进程内）。</summary>
        public static class Apps
        {
            /// <summary>经低权限代理在目标程序中执行代码并返回结果文本（对象为 JSON）。停止脚本只中止等待，已发送的代码仍会执行完。错误码：APP_UNAVAILABLE（未安装/未运行/代理不可用）、APP_FAILED（程序返回的错误）、APP_TIMEOUT。</summary>
            public static extern string? Run(string app, string code, bool wait = true, int timeoutMs = 30000, bool launch = false);
            /// <summary>调用软件连接（Bridge 插件）命令并返回解码后的结果（对象为 Dictionary、数组为 List，同 Browser.Eval；没有结果为 null）；需在 设置 → 软件连接 中开启，且目标软件的插件已连接。错误码：BRIDGE_DISABLED、BRIDGE_TARGET_NOT_FOUND、BRIDGE_TARGET_AMBIGUOUS（多个实例，请从目标窗口触发）、BRIDGE_TIMEOUT、BRIDGE_BUSY（软件连接正在切换，稍后重试）；插件返回失败时报 BRIDGE_FAILED，插件自己的错误码在 e.Detail；结果不是有效 JSON 或超过 1 MiB/10000 项等数据上限时报 BRIDGE_FAILED（e.Detail 为 RESULT_INVALID），此时命令可能已在目标软件中执行，请勿盲目重试。</summary>
            public static extern object? Bridge(string app, string command, object? arguments = null, int timeoutMs = 30000, string? target = null);
            /// <summary>软件连接中该软件的已连接实例（含其当前文档标题与路径）；没有返回空数组（motuyun 恒为空）；Id 可传给 Bridge 的 target；软件连接未开启报 BRIDGE_DISABLED。</summary>
            public static extern BridgeTarget[] ListTargets(string app);
            /// <summary>在 Office 当前文档中执行功能区命令（ExecuteMso）；程序须已运行（不会在后台启动，否则 APP_UNAVAILABLE），命令无效 APP_FAILED，弹出对话框的命令超时报 APP_TIMEOUT。</summary>
            public static extern void RunOfficeCommand(string app, string msoId, int timeoutMs = 10000);
        }

        /// <summary>调用 AI 模型（问答、提取、分类、看图、对话）与机器翻译；纯计算的文本工具见 qk.Text。按 Quicker 全局 AI 配置调用模型（useCase 为用例 Id，缺省 text.general），以及机器翻译（经 Quicker 服务器，可能消耗 Quicker 点数）；使用你的 AI 额度/配置。timeoutMs 为单次超时（默认 120000；0 为只受动作超时约束）。</summary>
        public static class Ai
        {
            /// <summary>对话，返回模型回复文本。使用你的 Quicker AI 配置与额度；错误码 AI_FAILED（未配置/模型错误）、AI_TIMEOUT（timeoutMs 到期或连接中断）；输入文本合计最多 20 万字符。</summary>
            public static extern string Ask(string prompt, string? system = null, string? useCase = null, IEnumerable<ChatMessage>? history = null, double? temperature = null, int maxTokens = 0, int timeoutMs = 120000);
            /// <summary>按 JSON Schema 从文本提取结构化数据，返回 JsonNode（node["字段"]?.GetValue&lt;string&gt;() 读取）；模型须支持结构化输出。</summary>
            public static extern JsonNode? Extract(string text, string schema, string? instructions = null, string? useCase = null, int timeoutMs = 120000);
            /// <summary>把文本归入一个类别（用例 text.general）；模型给出未知类别且没有 defaultValue 时报 AI_FAILED。</summary>
            public static extern ClassifyResult Classify(string text, IDictionary<string, string> categories, string? defaultValue = null, string? instructions = null, int timeoutMs = 120000);
            /// <summary>看图回答问题（缺省用例 image.understanding，模型须支持图片输入）。</summary>
            public static extern string AskImage(Img image, string prompt, string? system = null, string? useCase = null, int timeoutMs = 120000);
            /// <summary>机器翻译（经 Quicker 服务器，可能消耗 Quicker 点数，消耗数写入运行日志）；单次最多 1 万字符、每次运行累计最多 10 万字符（超出 LIMIT_EXCEEDED）；失败报 TRANSLATE_FAILED，超过 timeoutMs（默认 120000）报 TRANSLATE_TIMEOUT。</summary>
            public static extern string Translate(string text, string targetLanguage = "zh", string? sourceLanguage = null, string? vendor = null, int timeoutMs = 120000);
            /// <summary>打开交互式 AI 对话窗口：先发送 prompt，用户可追问；点“采用”返回结果，关闭/取消返回 null。等待用户操作（不受 AI 请求超时限制，受动作超时约束）；计入对话框限额。</summary>
            public static extern ChatResult? Chat(string prompt, string? conversationId = null, string? system = null, string? title = null, string? useCase = null, int maxRounds = 10, int maxTokens = 0);
            /// <summary>打开问问AI并携带提示词及 Materials。默认预填后返回；AutoSend=true 等待 Host 接受后返回，不等待回答，不返回回答。文件按规则导入内容或附带路径。窗口句柄 -1 不附带，0 为调用时前台。</summary>
            public static extern OpenAssistantResult OpenAssistant(OpenAssistantOptions options);
        }

        /// <summary>其他程序窗口里的界面元素（查找/读取/操作）；Quicker 自己的对话框见 qk.Ui，窗口本身见 qk.Window。window 为 null 表示前台窗口。El 仅本次运行有效；Find 找不到返回 null，元素消失或所在窗口关闭后使用 El 报 UIA_REF_STALE；Quicker 自身窗口不能读取也不能操作，报 UIA_TARGET_DENIED；无法确定所在窗口的元素按找不到处理。常见错误码：UIA_PATTERN_UNSUPPORTED（元素不支持该操作）、UIA_NOT_FOUND（菜单项/对话框）、UIA_TIMEOUT（程序无响应，单次 10 秒）、UIA_LIMIT_EXCEEDED（每次运行读取 400 次、操作 100 次、El 1024 个、累计 120 秒）。</summary>
        public static class Uia
        {
            /// <summary>查找第一个匹配的界面元素；没有返回 null。</summary>
            public static extern El? Find(Win? window = null, string? name = null, string? controlType = null, string? automationId = null, string? className = null, string? xpath = null, int timeoutMs = 0);
            /// <summary>查找全部匹配元素；没有返回空数组。条件同 Find（不支持 xpath）。</summary>
            public static extern El[] FindAll(Win? window = null, string? name = null, string? controlType = null, string? automationId = null, string? className = null, int limit = 64);
            /// <summary>屏幕点下的元素；没有返回 null。</summary>
            public static extern El? FromPoint(Pt? point = null);
            /// <summary>当前拥有键盘焦点的元素；没有返回 null。</summary>
            public static extern El? GetFocused();
            /// <summary>读取元素的最新信息快照（可返回）；XPath 相对元素自身所在的顶层窗口。</summary>
            public static extern ElInfo Info(El element);
            /// <summary>对元素执行操作。</summary>
            public static extern void Act(El element, string action = "invoke");
            /// <summary>设置元素的值（只用 Value 模式，如输入框、组合框，整体替换）；不支持或只读时报 UIA_PATTERN_UNSUPPORTED，不回退为键入（可先 Act(element, "focus") 再 qk.Keyboard.Paste）。</summary>
            public static extern void SetValue(El element, string value);
            /// <summary>窗口的界面元素树 JSON，用于编写脚本时查找名称、类型与 XPath。</summary>
            public static extern string GetTree(Win? window = null, int depth = 6, bool interactiveOnly = true);
            /// <summary>按路径点击窗口菜单，如 "文件/另存为"（名称含 / 时改用换行分隔层级）。每级先按 UIA 名称精确匹配，失败后两边都忽略访问键（(&amp;F)、(F)、&amp;）与末尾省略号（...、…）再比较，因此 "文件/另存为" 也能找到经典 Win32 菜单的“文件(F)”“另存为(A)...”；措辞或语言不同仍会失败。找不到某级报 UIA_NOT_FOUND，可先按 Escape 收起菜单再改用快捷键。</summary>
            public static extern void ClickMenu(string path, Win? window = null);
            /// <summary>作用于可识别的打开/另存为/选择文件夹对话框（前台的，否则第一个），否则报 UIA_NOT_FOUND。已存在的本地文件夹直接切换，不改文件名框；文件路径切到上级文件夹并只填文件名。网络路径或无法直接切换时回退为填写完整路径。资源管理器窗口见 qk.Files.SetExplorerPath。</summary>
            public static extern void SetDialogPath(string path, bool createDirectory = false, bool pressEnter = false);
        }

        /// <summary>Quicker 自身与账号服务（信息、命令、云端数据、临时分享、账号绑定加解密、一次性提醒）；调用其他动作见 qk.Actions。云端数据（GetCloud/SetCloud/RemoveCloud）按 Quicker 用户跨动作、跨设备共享。</summary>
        public static class Quicker
        {
            /// <summary>读取 Quicker 版本、专业版状态、用户标识（UnionId）、暂停状态、主题与运行时长。</summary>
            public static extern QuickerInfo Info();
            /// <summary>执行 Quicker 命令，发出即返回（showPanel 最多等 2 秒面板出现）；未知 command 报 INVALID_ARGUMENT（不开放退出 Quicker、删除动作等）。其他失败 QUICKER_COMMAND_FAILED。</summary>
            public static extern void Command(string command, string? argument = null);
            /// <summary>读取云端数据（按 Quicker 账号加密保存，该账号的所有动作、所有设备共享）；键不存在返回 null（空串是已保存的空值）。key 1–256 字符，不含控制字符与反斜杠；可用 / 分层（如 "myapp/count"），但不能以 / 开头、不能有空层级或 . / .. 层级。同一个键被该账号的所有动作共享，建议以动作名作前缀避免冲突。每次运行最多 200 次读写，另受每日次数限制（专业版 5000、免费版 500）；失败 CLOUD_FAILED（未登录、网络、15 秒超时等）。</summary>
            public static extern string? GetCloud(string key);
            /// <summary>写入云端数据（字符串；对象请先序列化为 JSON）；删除用 RemoveCloud（value 为 null 报 INVALID_ARGUMENT）；不支持过期时间。值上限：专业版 100 万字符、免费版 10 万字符（LIMIT_EXCEEDED）；"*NULL*" 是存储的保留删除值，不能作为值（INVALID_ARGUMENT）。多设备同时写入以最后一次为准；停止脚本时已发出的写入仍可能生效。读-改-写（列表、计数）时：在 SetCloud 之前立即重新 GetCloud，按 id/键修改这份最新值（不要用早先读取时的序号），然后马上 SetCloud。</summary>
            public static extern void SetCloud(string key, string value);
            /// <summary>删除云端数据（键不存在也不报错）；键规则、次数与超时同 SetCloud；停止脚本时已发出的删除仍可能生效。</summary>
            public static extern void RemoveCloud(string key);
            /// <summary>上传文本（string，1–100 万字符，存为 .txt）或图片（Img，编码为 PNG，最多 10 MB）到 Quicker 临时分享并返回网址。会生成他人可访问的网址：任何拿到网址的人都能打开，不要分享敏感内容；有效期由服务器决定（临时，不要当作存储）。每次运行最多 20 次，另有上传间隔（专业版 2 秒、免费版 1 分钟）；失败 TEMP_SHARE_FAILED。</summary>
            public static extern string ShareTemporary(object content);
            /// <summary>上传本机文件（最多 10 MB）到 Quicker 临时分享并返回网址（他人可访问，有效期由服务器决定）。</summary>
            public static extern string ShareTemporaryFile(string path, bool randomName = false);
            /// <summary>“自用加密”（与“加密解密”步骤的自用加密逐字节互通）：UTF-8 文本 → AES（固定 IV）→ Base64。密钥只由 Quicker 账号决定（同账号任意设备/动作可解，相同明文得到相同密文，无完整性校验），不适合对抗性场景；未登录报 ACCESS_DENIED。</summary>
            public static extern string EncryptLocal(string text);
            /// <summary>解密“自用加密”的 Base64 密文，返回 UTF-8 文本；可解开本账号下任何动作保存的密文。密文无效、不是本账号加密或结果不是 UTF-8 报 INVALID_ARGUMENT；未登录报 ACCESS_DENIED。</summary>
            public static extern string DecryptLocal(string cipherText);
            /// <summary>创建一次性提醒并返回提醒 Id：脚本不必等待（qk_run 整次运行最多 30 秒），到点由 Quicker 自身弹出常驻通知（标题 + 正文，不抢焦点）。按账号落盘，Quicker 重启后仍有效；到点时 Quicker 没运行的，会在下次启动时补一次并标注“（已错过，原定 HH:mm）”。dueAt（具体时刻）与 delayMs（多少毫秒后，long）必须恰好给一个，时间须在现在之后 5 秒到 30 天之内，否则 INVALID_ARGUMENT；title 1–100 字符，text 至多 1000 字符。没有“修改”：要改请先 CancelReminder 再重新 Remind；脚本重复运行会重复创建提醒（需要去重请先 ListReminders）。提醒归创建它的动作（qk_run 为 AI 一次性脚本）所有：ListReminders / CancelReminder 只看得到、取消得了自己创建的；安装来源的脚本需要用户确认“设置提醒”。每个账号最多 50 条待触发提醒、同一动作最多 20 条、每次运行最多新建 20 条，超出 LIMIT_EXCEEDED。提醒、定时的需求不要新建动作，也不要在脚本里等待。</summary>
            public static extern string Remind(string title, string? text = null, DateTimeOffset? dueAt = null, long? delayMs = null);
            /// <summary>列出本动作自己创建的待触发提醒，按触发时间升序（已触发、已取消的与其他动作的提醒不在其中）。</summary>
            public static extern ReminderInfo[] ListReminders();
            /// <summary>按提醒 Id 取消本动作自己创建的一条待触发提醒；Id 不存在（含已触发）或不是本动作创建的返回 false，不报错。</summary>
            public static extern bool CancelReminder(string id);
        }

        /// <summary>纯计算的文本工具（哈希、拼音、HTML 解析）；显示文本见 qk.Ui.ShowText。</summary>
        public static class Text
        {
            /// <summary>计算哈希或 HMAC，如 Hash("abc", "md5") == "900150983cd24fb0d6963f7d28e17f72"；API 签名常用 Hash(body, "sha256", secret, "base64")。文件内容的哈希请用 qk.Files.Hash(path)（流式计算，不受 16 MiB 限制）。</summary>
            public static extern string Hash(object data, string algorithm = "sha256", string? hmacKey = null, string output = "hex");
            /// <summary>汉字转拼音（无声调、小写；非汉字原样保留）；未给 all 时按词组判断多音字（"重庆" → "chong qing"）。</summary>
            public static extern string ToPinyin(string text, bool initials = false, bool allReadings = false, string? separator = null);
            /// <summary>text 是否匹配 query（包含、全拼、首字母或混合；空格分隔的多个词须都匹配、顺序不限；忽略大小写；query 为空返回 true），与 Quicker 搜索同一规则。如 "中文输入法" 匹配 "zwsrf"、"zhongwen"、"srf zw"。</summary>
            public static extern bool MatchPinyin(string text, string query);
            /// <summary>HTML 转纯文本（同“文本处理”步骤的 html2text）：去掉 script/style/注释、解码实体，只有 p/br 换行；只解析传入的字符串（网址/路径也按文本处理）；最多 16 M 字符、嵌套 1000 层。</summary>
            public static extern string HtmlToText(string html);
            /// <summary>用 XPath 1.0 查询 HTML（以 / 、( 或 . 开头；不支持 CSS 选择器；元素名与属性名用小写），每个匹配节点返回一个字符串；"//a/@href" 等同 attribute: "href"；无匹配返回空数组；XPath 错误报 INVALID_ARGUMENT；最多 10000 个结果。</summary>
            public static extern string[] QueryHtml(string html, string xpath, string? attribute = null, string output = "text");
        }

        /// <summary>Windows 与本机（系统信息、CPU 与内存占用、环境变量与注册表读取、提示音、朗读、音量与音频设备、媒体键、磁盘、网络与 Wi-Fi、Windows 设置页（SearchSettings/OpenSettings）、显示器亮度、深色模式、锁屏/关屏/睡眠/关机等电源操作）；Quicker 自身的信息见 qk.Quicker。</summary>
        public static class Sys
        {
            /// <summary>读取计算机名、用户名、系统版本、锁屏/全屏/深色模式/联网状态、局域网 IP 与开机时长。</summary>
            public static extern SysInfo Info();
            /// <summary>播放声音；每次运行 PlaySound 与 Speak 合计最多 100 次；无法解码或没有音频设备报 SOUND_FAILED（不等待时只记警告）。</summary>
            public static extern void PlaySound(string sound, bool wait = false);
            /// <summary>播放声音；每次运行 PlaySound 与 Speak 合计最多 100 次；无法解码或没有音频设备报 SOUND_FAILED（不等待时只记警告）。</summary>
            public static extern void PlaySound(string sound, bool wait = false, double volumeGain = 1);
            /// <summary>用 Windows 默认语音朗读文本（1–20000 字符）；语音引擎不可用报 SOUND_FAILED。</summary>
            public static extern void Speak(string text, bool wait = false);
            /// <summary>读取当前默认输出设备（或默认录音设备）的音量与静音（每次调用都重新取默认设备）；没有音频设备报 SOUND_FAILED。停止后的 finally 中也可调用。</summary>
            public static extern VolumeInfo GetVolume(string device = "output");
            /// <summary>设置当前默认输出设备（或默认录音设备，如麦克风静音）的音量与静音，返回调用后的状态；运行后保留（宿主不自动恢复：先 GetVolume 保存，在 finally 中 SetVolume 恢复，停止后的 finally 中也可调用）；没有音频设备报 SOUND_FAILED。</summary>
            public static extern VolumeInfo SetVolume(int? level = null, bool? muted = null, string device = "output");
            /// <summary>电源与会话操作。lock、screenOff 锁定或关闭屏幕；sleep/hibernate/signOut/shutdown/restart 可使电脑睡眠、休眠、注销、关机或重启，未保存的工作可能丢失。失败报 POWER_FAILED。screenOff 由鼠标或按键触发时，随后的鼠标移动或松键可能立即点亮屏幕。睡眠期间停止与超时不生效；唤醒后若已超过动作超时，后续代码不再执行。</summary>
            public static extern void Power(string action);
            /// <summary>读取显示器亮度 0–100（同“显示器亮度”步骤：笔记本内置屏走 WMI，外接显示器走 DDC/CI）。不支持调节亮度报 BRIGHTNESS_UNSUPPORTED，其他失败（屏幕未连接等）报 BRIGHTNESS_FAILED。</summary>
            public static extern int GetBrightness(string screen = "mouse");
            /// <summary>设置显示器亮度，返回设置后的亮度；设备只支持部分档位时取最接近的档位；运行后保留。screen 为 all 时设置全部显示器，至少一块成功即返回（鼠标所在屏，否则第一块成功屏的亮度），全部失败才报错。错误码同 GetBrightness。</summary>
            public static extern int SetBrightness(int? level = null, int delta = 0, string screen = "mouse", bool osd = false);
            /// <summary>列出已启用的音频输出（或录音）设备，IsDefault 标出当前默认设备；读取失败报 SOUND_FAILED。</summary>
            public static extern AudioDevice[] ListAudioDevices(string device = "output");
            /// <summary>设为默认音频设备（多媒体、控制台与通信，同“音频控制”步骤）；运行后保留。找不到 AUDIO_DEVICE_NOT_FOUND；名称匹配到多个 INVALID_ARGUMENT（请改用 Id）；设置失败 SOUND_FAILED。</summary>
            public static extern void SetDefaultAudioDevice(string idOrName, string device = "output");
            /// <summary>读取环境变量（Quicker 进程中的当前值；Quicker 启动后在系统设置中修改的变量需重启 Quicker 才可见）；不存在返回 null。</summary>
            public static extern string? GetEnv(string name);
            /// <summary>读取注册表值（只读）；键或值不存在返回 null。REG_SZ/REG_EXPAND_SZ → string（已展开）、REG_DWORD → long（无符号）、REG_QWORD → long、REG_MULTI_SZ → string[]、REG_BINARY → byte[]；无权限报 ACCESS_DENIED。</summary>
            public static extern object? GetRegistry(string path, string? name = null);
            /// <summary>切换当前用户的 Windows 深色（true）/浅色（false）模式，并通知已打开的程序（个别程序重启后才生效）；运行后保留，当前状态见 qk.Sys.Info().DarkMode。</summary>
            public static extern void SetDarkMode(bool dark, string scope = "all");
            /// <summary>发送系统媒体播放键。全局生效，不需要目标窗口或键盘焦点（qk_run 的 target:'none' 可用）；响应的播放器由系统决定；只能发送这四个键（音量与静音请用 Sys.SetVolume）。失败报 HOST_FAILED。</summary>
