    /// <summary>非等待文本窗口句柄（qk.Ui.OpenText 返回）：仅本次运行有效，不能返回或写入 State；窗口本身在运行结束后保留，由用户关闭。窗口关闭后 Append/SetText/Activate/Close 不做任何事（用 Closed 判断）。停止后的 finally 中仍可对它调用 Close/Append/SetText（清理阶段合计最多 64K 字符）；读取 Closed 任何时候都可用。</summary>
    public partial class TextWin
    {
        /// <summary>窗口是否已关闭（用户关闭、点 operations 按钮、调用 Close、被同 Key 窗口替换）。</summary>
        public bool Closed { get; }
        /// <summary>在末尾追加文本（光标移到末尾）；窗口内容最多 4M 字符。</summary>
        public extern void Append(string text);
        /// <summary>替换全部文本（光标移到开头）。</summary>
        public extern void SetText(string text);
        /// <summary>显示并激活窗口（最小化时还原）。</summary>
        public extern void Activate();
        /// <summary>等待用户关闭窗口（点 X、Esc、失焦关闭或点击 operations 按钮——点击 operations 按钮即关闭窗口），返回关闭时的文本、选中内容、光标与 Operation（点击的 operations 值，否则 null）；被 Close 关闭、被同 options.Key 的 OpenText 替换或运行结束时返回 null；运行被停止时中断等待。</summary>
        public extern TextResult? WaitForClose();
        /// <summary>关闭窗口（之后 WaitForClose 返回 null）；已关闭时无操作。</summary>
        public extern void Close();
    }

