        public extern UiOptions(string? Title = null, string? Help = null, string Position = "mouse", Rect? Bounds = null, bool Topmost = true, bool RestoreFocus = true, bool CloseOnBlur = false, bool NoFocus = false, int FontSize = 0, string? Font = null, string? Ime = null, int AutoCloseMs = 0, string? Key = null, bool ShowMinimizeButton = false, bool ShowMaximizeButton = false, bool AllowResize = false);
        /// <summary>窗口标题；缺省为动作标题。</summary>
