        /// <summary>窗口位置：mouse|mouse2|center|topLeft|topCenter|topRight|leftCenter|rightCenter|bottomLeft|bottomCenter|bottomRight|last；last 仅 Select/SelectMany 支持，其余降级为 mouse；Alert/Confirm/Ask 与文件对话框忽略。</summary>
        public string Position { get; set; }
        /// <summary>指定窗口矩形（物理像素），优先于 Position；Select/SelectMany/Form/ShowText 支持，Prompt/PromptNumber/PromptDate 降级为 mouse，Alert/Confirm/Ask 与文件对话框忽略。</summary>
        public Rect? Bounds { get; set; }
        /// <summary>是否置顶。</summary>
        public bool Topmost { get; set; }
        /// <summary>关闭后是否恢复原前台窗口。</summary>
        public bool RestoreFocus { get; set; }
        /// <summary>失去焦点时自动关闭：Select/Prompt/PromptDate 视为取消（返回 null）；ShowText 照常返回关闭时的结果。</summary>
