        /// <summary>输入法：on|off；null 为不切换。</summary>
        public string? Ime { get; set; }
        /// <summary>自动关闭时长（毫秒；0 为不自动关闭；窗口按整秒计时，不足 1 秒向上取整）。仅 Select/SelectMany/ShowImage 使用。</summary>
        public int AutoCloseMs { get; set; }
        /// <summary>窗口标识：再次显示同 Key 窗口时，关闭本动作仍打开的旧窗口并沿用其位置（仅 Select/SelectMany/ShowText 使用）；按动作隔离，位置不持久化。</summary>
        public string? Key { get; set; }
        /// <summary>仅 Ui.React：显示最小化按钮，默认 false。</summary>
